function drawPsyduckHeadacheDuck(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.1;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 3.0;

  const headacheWiggle = Math.sin(t * 8.0) * 1.5;

  // Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 26 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // Chân màng bơi
  ctx.fillStyle = '#fde047';
  ctx.beginPath(); ctx.roundRect(-18, by + 28, 10, 8, 3); ctx.fill();
  ctx.beginPath(); ctx.roundRect(8,   by + 28, 10, 8, 3); ctx.fill();

  // Thân vàng
  ctx.fillStyle = '#facc15';
  ctx.beginPath(); ctx.ellipse(0, by + 12, 20 * sX, 18 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // Đầu vàng
  ctx.beginPath(); ctx.ellipse(0, by - 10, 20 * sX, 16 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // 3 cọng tóc đen
  ctx.strokeStyle = '#0f172a';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(0,  by - 26); ctx.lineTo(0,  by - 38);
  ctx.moveTo(-4, by - 25); ctx.lineTo(-8, by - 36);
  ctx.moveTo(4,  by - 25); ctx.lineTo(8,  by - 36);
  ctx.stroke();

  // Mỏ vịt kem
  ctx.fillStyle = '#fef08a';
  ctx.beginPath(); ctx.ellipse(0, by - 5, 14, 9, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#ca8a04';
  ctx.fillRect(-2, by - 6, 1, 1);
  ctx.fillRect(2,  by - 6, 1, 1);

  // Mắt ngơ ngác
  if (!blink) {
    ctx.fillStyle = '#ffffff';
    ctx.strokeStyle = '#ca8a04';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(-10, by - 14, 5, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    ctx.beginPath(); ctx.arc(10,  by - 14, 5, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    ctx.fillStyle = '#0f172a';
    ctx.beginPath(); ctx.arc(-10, by - 14, 1.2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(10,  by - 14, 1.2, 0, Math.PI * 2); ctx.fill();
  }

  // Tay ôm đầu
  ctx.fillStyle = '#facc15';
  ctx.beginPath(); ctx.roundRect(-24 + headacheWiggle, by - 14, 8, 16, 4); ctx.fill();
  ctx.beginPath(); ctx.roundRect(16 - headacheWiggle,  by - 14, 8, 16, 4); ctx.fill();

  ctx.restore();
}
